  var CITY_TOP = { '北京市': 1, '天津市': 1, '上海市': 1, '重庆市': 1, '香港特别行政区': 1, '澳门特别行政区': 1 };

  function norm(s) {
    return String(s || '').replace(/[省市区县镇乡自治特别行政]/g, '').toLowerCase().trim();
  }

  /* 按输入返回本地匹配城市（Open-Meteo results 结构），最多 8 条。
   * 命中省级时返回该省下辖条目（直辖市/港澳特别行政区保留省级条目在首位）。 */
  window.localGeoResults = function (q) {
    var n = norm(q);
    if (!n) return [];
    var out = [];
    CITIES.forEach(function (c) {
      var names = [c.name].concat(c.aliases || []);
      for (var i = 0; i < names.length; i++) {
        var nm = norm(names[i]);
        if (nm && (nm.indexOf(n) === 0 || n.indexOf(nm) === 0)) { out.push(c); break; }
      }
    });
    if (!out.length) return [];
    var provHit = null;
    for (var j = 0; j < out.length; j++) {
      if (out[j]._lv === 'p') { provHit = out[j]; break; }
    }
    if (provHit) {
      var cityRows = [], countyRows = [];
      CITIES.forEach(function (c) {
        if (c._lv === 'p' || c.admin1 !== provHit.admin1) return;
        (c._lv === 'd' ? cityRows : countyRows).push(c);
      });
      if (CITY_TOP[provHit.name]) {
        return [provHit].concat(countyRows.slice(0, 7));
      }
      var list = cityRows.slice(0, 8);
      if (list.length < 8) list = list.concat(countyRows.slice(0, 8 - list.length));
      return list;
    }
    return out.slice(0, 8);
  };

  /* 合并本地与远程结果：本地优先，按 name|admin1 去重，最多 8 条 */
  window.mergeGeoResults = function (local, remote) {
    var out = [], seen = {};
    function push(r) {
      if (!r || typeof r !== 'object') return;
      var key = (r.name || '') + '|' + (r.admin1 || '');
      if (seen[key]) return;
      seen[key] = 1;
      out.push(r);
    }
    (local || []).forEach(push);
    (remote || []).forEach(push);
    return out.slice(0, 8);
  };
